MongoClient mongoClient = new MongoClient();
  DBCollection coll = mongoClient.getDB("events").getCollection("messages");

  // find the last message
  ObjectId lastEntryId = (ObjectId)coll.find().sort(BasicDBObjectBuilder.start("$natural", -1).get()).limit(1).next().get("_id");

  DBObject query = QueryBuilder.start("_id").greaterThan(lastEntryId).get();


  DBCursor cur = coll.find(query).sort(BasicDBObjectBuilder.start("$natural", 1).get()).addOption(Bytes.QUERYOPTION_TAILABLE).addOption(Bytes.QUERYOPTION_AWAITDATA);

  System.out.println("== open cursor ==");

  Runnable task = () -> {
      System.out.println("\tWaiting for events");
      while (cur.hasNext()) {
          DBObject obj = cur.next();
          System.out.println( obj.get("text") );

      }
  };
  new Thread(task).start();

